input.command:
cd /home/runner/work/PlayGround/PlayGround && node - <<'NODE'
const { chromium } = require('playwright');
(async() => {
  const browser = await chromium.launch({headless:true});
  const page = await browser.newPage({ viewport:{width:1280, height:720}});
  await page.goto('http://localhost:8123');
  console.log('title', await page.title());
  await page.click('#startBtn');
  console.log('after click status', await page.locator('#statusTitle').textContent());
  console.log('after click hidden?', await page.locator('#overlay').evaluate(el => el.classList.contains('hidden')));
  await page.waitForTimeout(1500);
  console.log('after ~1.5s status', await page.locator('#statusTitle').textContent(), 'hint', await page.locator('#statusHint').textContent());
  console.log('telegraph', await page.locator('#telegraph').textContent());
  // Check if game is in ready/windup by reading body
  const v = await page.evaluate(() => {
    const root = document.getElementById('statusTitle');
    return {
      title: root.textContent,
      telegraph: document.getElementById('telegraph').textContent,
      overlayHidden: document.getElementById('overlay').classList.contains('hidden'),
      enemyHp: document.getElementById('enemyHealth').textContent,
      playerHp: document.getElementById('playerHealth').textContent,
    };
  });
  console.log(v);
  await browser.close();
})();
NODE

